#include <iostream>
using namespace std;

int main() {
    int N, R;
    cin >> N >> R;

    for (int i = 0; i < N; i++) {
        int division, score;
        cin >> division >> score;

        if (division == 1) // Div. 1 なら
            // Div. 1 の条件をもとに、更新対象ならレーティングを更新
            if (1600 <= R && R <= 2799)
                R += score;

        if (division == 2) // Div. 2 なら
            // Div. 2 の条件をもとに、更新対象ならレーティングを更新
            if (1200 <= R && R <= 2399)
                R += score;
    }

    // 最終的なレーティングを出力
    cout << R << endl;
    return 0;
}
